function hideOriginalCrosshair(config) {
	if (
		config.variant === "period" ||
		(Array.isArray(config.variant) && config.variant.inclues("period"))
	) {
		return {
			stroke: "#000000",
			strokeWidth: 0,
			strokeOpacity: 0,
		};
	}
	return false;
}

