import { Component, Element, Host, Prop, h } from "@stencil/core";
import retargetEvents from "react-shadow-dom-retarget-events";
import { renderChart } from "./RenderChart";

/**
 * @since 0.0.6
 * @status beta
 *
 */
@Component({
	tag: "hbr-line",
	styleUrl: "line.scss",
	shadow: true,
})
export class HbrLine {
	/**
	 * config object for the chart,
	 * refer: https://nivo.rocks/line
	 */
	@Prop() config: any = { data: [] };
	/**
	 * width of the container in CSS length units
	 */
	@Prop() width = "100%";
	/**
	 * height of the container in CSS length units
	 */
	@Prop() height = "360px";
	/**
	 * variant
	 */
	@Prop() variant: string | Array<string> = "";
	/**
	 * threshold
	 */
	@Prop() threshold: number | undefined = undefined;
	/**
	 * disable the first legend when only one data set
	 */
	@Prop() noFirstLegend = true;
	@Element() private el: HTMLHbrLineElement;

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot = null;

	componentDidLoad() {
		this.createChart();
		retargetEvents(this.el.shadowRoot);
	}
	componentDidUpdate() {}

	componentShouldUpdate() {
		this.createChart();
		return false;
	}

	createChart() {
		const root = this.el.shadowRoot.querySelector("div");
		this.config._threshold = this.threshold;
		this.config._noFirstLegend = this.noFirstLegend;
		this.contextRoot = renderChart({
			el: root,
			variant: this.variant,
			config: this.config,
			contextRoot: this.contextRoot,
		});
	}

	render() {
		this.el.style.width = this.width;
		this.el.style.height = this.height;
		return (
			<Host>
				<div
					id="root"
					style={{ width: this.width, height: this.height }}
					class={{
						"default-tooltip": !this.config.sliceTooltip,
						"hide-tooltip-color-dot":
							this.noFirstLegend && this.config?.data?.length === 1,
					}}
				/>
			</Host>
		);
	}
}
