import { isDate } from "./index";

const getAxisBottomFormat = (value: Date | string | undefined): string => {
	if (!value) return "";
	if (!isDate(value)) return "";
	const _value = new Date(value) as Date;
	const meridiem = _value.toLocaleTimeString("en-US").slice(-2);
	let hour = _value.getHours().toString();
	hour = hour.length === 1 ? `0${hour}` : hour;
	if (hour === "00") {
		const month = new Intl.DateTimeFormat("en-US", { month: "short" }).format(
			_value.getMonth(),
		);
		const day = _value.getUTCDate();
		return `${month} ${day}`;
	}
	return `${hour} ${meridiem}`;
};

export default getAxisBottomFormat;
