import { isNumber } from "./index";

const getThresholdValue = (config: any) => {
	if (isNumber(config._threshold)) return config._threshold;
	if (Array.isArray(config.markers) && config.markers.length) {
		const threshold = config.markers
			.filter((marker) => marker.axis === "y" && isNumber(marker.value))
			.map((marker) => marker.value);
		if (threshold.length) return threshold;
	}
	return null;
};

export default getThresholdValue;
