import { getColors } from "../../../../utils/charts";

export default function getLegends(config, margin) {
	let colors = Array.isArray(config.colors)
		? config.colors
		: getColors(config.data.length);
	if (typeof config.colors === "string") colors = [config.colors];
	const legends = [
		{
			dataFrom: "id",
			data: config.data.map((d, i) => ({
				color: colors[i],
				id: d.id,
				label: d.id,
			})),
			anchor: "bottom-left",
			direction: "row",
			justify: false,
			translateX: 0,
			translateY: typeof margin?.top === "number" ? margin?.top * -1 : 0,
			itemsSpacing: 0,
			itemWidth: 80,
			itemDirection: "left-to-right",
			itemHeight: 20,
			//itemOpacity: 0.75, removing this so legend dots can fade with overwriting opacity on hover
			symbolSize: 12,
			symbolShape: "circle",
			symbolBorderColor: "rgba(0, 0, 0, .5)",
			effects: [],
		},
	];
	if (!Array.isArray(config.data)) return [];
	if (config._variant === "small") return [];
	return legends;
}
