import React from "react";

const CustomPoints = (props) => {
	const points = props.points.reduce((acc, point, i) => {
		let show = false;

		if (props.currentSlice) {
			let points = props.currentSlice.points;
			if (Array.isArray(points)) {
				points = [...points].reverse();
			}
			points.forEach((_point, _i) => {
				if (_point.x === point.x && _point.y === point.y) show = true;
				else show = false;
				if (point.data.__isolatedPoint) show = true;
				const _props = {
					key: `${i} ${_i}`,
					cx: point.x,
					cy: point.y,
					r: "3",
					fill: point.serieColor,
					style: { visibility: show ? "visible" : "hidden" },
				};
				acc.push(React.createElement("circle", _props));
			});
			return acc;
		}
		if (point?.data.__isolatedPoint) {
			const _props = {
				key: `${i}`,
				cx: point.x,
				cy: point.y,
				r: "3",
				fill: point.serieColor,
				style: { visibility: true },
			};
			acc.push(React.createElement("circle", _props));
		}
		return acc;
	}, []);
	return points;
};

export default CustomPoints;
