const isIncludes = (variant: string | string[], str: string): boolean =>
	Array.isArray(variant) && variant.includes(str);

export default function getVariant(variant: string | string[]): object {
	switch (variant) {
		case "small" || isIncludes(variant, "small"):
			return {
				margin: { top: 2, right: 2, bottom: 2, left: 2 },
				yScale: { min: "auto", max: "auto" },
				isInteractive: false,
				axisBottom: null,
				gridYValues: 0,
				gridXValues: 0,
				axisLeft: {
					tickValues: [],
					legend: "",
				},
			};
		default:
			return {};
	}
}
