const getMarkers = (threshold: number | undefined) => {
	return threshold
		? [
				{
					axis: "y",
					value: threshold,
					lineStyle: {
						stroke: "var(--hbr-color-neutral-text-weak)",
						strokeWidth: 1,
						strokeDasharray: "4, 2",
					},
				},
		  ]
		: [];
};

export default getMarkers;
