import { isDate } from "./index";
function getGridXValues(config: any): Array<string | Date> {
	const ticksArrays = [];
	if (config.axisBottom?.tickValues !== "every 2 hours") return ticksArrays;
	const { data, xScale = {} } = config;
	const { type } = xScale;
	if (type === "time" || !type) {
		if (!Array.isArray(config.data)) return ticksArrays;
		if (data.length && Array.isArray(data[0].data)) {
			data[0].data.forEach((t) => {
				let _date = t.x;
				if (typeof t.x === "string") {
					_date = new Date(t.x);
				}
				if (
					isDate(_date) &&
					_date.getHours() % 2 === 0 &&
					_date.getMinutes() === 0
				) {
					ticksArrays.push(_date.getTime());
				}
			});
		}
		return ticksArrays;
	}
}

export default getGridXValues;
