import { BoxLegendSvg } from "@harbor-charts/legends";
import React, { memo } from "react";
import { isThreshold } from "../util";

const CustomThresholdSymbolShape = ({
	id,
	x,
	y,
	size,
	fill,
	borderWidth,
	borderColor,
}) => {
	const rect = React.createElement("rect", {
		key: "rect",
		height: 8,
		width: 15,
		x: 0,
		y: 7,
		fill: "rgba(212, 55, 28, 0.15)",
	});
	const line = React.createElement("line", {
		key: "line",
		x1: 0,
		y1: 7,
		x2: 15,
		y2: 7,
		stroke: "var(--hbr-color-neutral-text-weak)",
		strokeWidth: 1,
		strokeDasharray: "2, 4",
	});
	return React.createElement(
		"g",
		{
			key: id,
			id: "thresholdIcon",
			name: "threshold",
			x,
			y,
			fill,
			strokeWidth: borderWidth,
			stroke: borderColor,
			width: size,
			height: size,
			style: {
				pointerEvents: "none",
				display: id === "threshold" ? "block" : "none",
			},
		},
		[line, rect],
	);
};

const CustomLegends = (props) => {
	const { height, legends, width, data } = props;
	const noFirstLegend = data.length === 1 && props._noFirstLegend;
	if (!Array.isArray(legends) || (noFirstLegend && !isThreshold(props)))
		return React.createElement(React.Fragment, {});
	let _legends = Array.from(legends);
	if (
		Array.isArray(legends) &&
		data.length &&
		isThreshold(props) &&
		legends.length
	) {
		const lastValue = legends[legends.length - 1];
		const thresholdData = { ...lastValue };
		thresholdData.symbolShape = CustomThresholdSymbolShape;
		const legendsData = thresholdData.data.map((_, i) => ({
			id: i,
			color: "transparent",
			label: "",
		}));
		if (noFirstLegend) {
			thresholdData.data = [
				{
					color: "",
					id: "threshold",
					label: "Threshold",
				},
			];
		} else {
			thresholdData.data = [
				...legendsData,
				{
					color: "",
					id: "threshold",
					label: "Threshold",
				},
			];
		}
		thresholdData.isThreshold = true;
		if (noFirstLegend) _legends = [{ ...thresholdData }];
		else _legends = [{ ...thresholdData }, ..._legends];
	}
	const LegendsNodes = _legends.map((legend: any, i: number) => {
		let paths = [] as NodeListOf<SVGElement> | Array<undefined>;
		return React.createElement(BoxLegendSvg, {
			key: i,
			...legend,
			style: { cursor: "default" },
			containerHeight: height,
			containerWidth: width,
			onMouseEnter: legend.isThreshold
				? (_data, event) => {
						if (event.currentTarget) {
							const g = event.currentTarget.closest("g");
							if (!g) return;
							const rect = g.querySelector("rect");
							if (rect) rect.style = "cursor: default";
						}
				  }
				: (_data, event) => {
						const root = event.currentTarget.closest("svg") as HTMLElement;
						paths = root.querySelectorAll(
							"svg path[stroke]",
						) as NodeListOf<SVGElement>;
						Array.from(paths)
							.filter((p) => p.getAttribute("stroke") !== _data.color)
							.forEach((p: SVGElement) => {
								p.setAttribute("opacity", "0.1");
							});
				  },
			onMouseLeave: legend.isThreshold
				? () => {}
				: () => {
						if (legend.data.id === "threshold") return;
						Array.from(paths).forEach((p: SVGElement) => {
							p.setAttribute("opacity", "1");
						});
				  },
		});
	});
	return React.createElement(React.Fragment, {}, LegendsNodes);
};

export default (props) => React.createElement(memo(CustomLegends), props);
