import { ResponsiveLine as Line } from "@harbor-charts/line";
import merge from "deepmerge";
import React from "react";
import { createRoot } from "react-dom/client";
import { getBaseConfig } from "../../../utils/charts";
import { getColors } from "../../../utils/charts";
import { combineMergeArray } from "../../../utils/combineMergeArray";
import {
	getAxisBottomFormat,
	getGridXValues,
	getLayers,
	getLegends,
	getMarkers,
	getVariant,
	hideOriginalCrosshair,
	preprocessData,
} from "./util";

function getLineBaseConfig({ config }) {
	const _data = config.data;
	const _margin = { top: 10, right: 10, bottom: 50, left: 60 };
	const margin =
		typeof config.margin?.top === "number"
			? { ..._margin, ...config.margin }
			: _margin;
	return {
		margin: margin,
		curve: "catmullRom",
		enableSlices: "x",
		xScale: {
			type: "time",
			format: "native",
		},
		yScale: { type: "linear" },
		axisRight: null,
		data: preprocessData(config),
		axisBottom: {
			format: getAxisBottomFormat,
			tickSize: 0,
			fill: "var(--hbr-primary-text, #545454)",
			tickPadding: 10,
		},
		colors: config.colors || getColors(_data.length),
		axisLeft: {
			orient: "left",
			tickSize: 0,
			tickPadding: 10,
			tickRotation: 0,
			legend: "",
			legendOffset: -40,
			legendPosition: "middle",
		},
		enablePoints: false,
		pointColor: { theme: "background" },
		pointBorderColor: { from: "serieColor" },
		pointLabelYOffset: -12,
		theme: {
			fontSize: "var(--hbr-font-size-2xs)",
			fontFamily: "var(--hbr-font-body)",
			textColor: "var(--hbr-color-neutral-text-weak)",
			axis: {
				legend: {
					text: {
						fontSize: "var(--hbr-font-size-2xs)",
						fill: "var(--hbr-color-neutral-text-weak)",
					},
				},
			},
			grid: { line: { stroke: "var(--hbr-color-neutral-border)" } },
			crosshair: {
				line: hideOriginalCrosshair(config) || {
					stroke: "var(--hbr-color-neutral-text-weak)",
					strokeWidth: 1.5,
					strokeOpacity: 0.35,
					strokeDasharray: "3,3",
				},
			},
			tooltip: {
				basic: {
					background: "var(--hbr-color-neutral-bg)",
					fontSize: "var(--hbr-font-size-xs)",
					fontWeight: "350",
					color: "var(--hbr-color-neutral-text-weak)",
					fontFamily: "var(--hbr-font-body)",
				},
				container: {
					padding: "12px",
					background: "var(--hbr-color-neutral-bg)",
					boxShadow:
						"0px 0px 8px rgba(0, 0, 0, 0.08), 0px 4px 6px rgba(0, 0, 0, 0.15)",
					borderRadius: "8px",
				},
			},
		},
		layers: getLayers(config),
		enableGridX: true,
		gridXValues: getGridXValues(config),
		axisTop: null,
		animate: false,
		isInteractive: true,
		useMesh: true,
		legends: getLegends(config, margin),
		markers: getMarkers(config._threshold),
	};
}

export function renderChart(params: any) {
	const { el, variant, config, contextRoot } = params;
	config._variant = variant;
	/**
	 * merges: common charts config < bar charts common config < config from user
	 * TODO: do we need un modifiable config?
	 */
	const _variant = variant ? getVariant(variant) : {};
	const _config: any = merge.all(
		[getBaseConfig(), getLineBaseConfig(params), _variant, config],
		{
			arrayMerge: combineMergeArray,
		},
	);

	if (!el.innerHTML.length) {
		const newRoot = createRoot(el);
		/* @ts-ignore */
		newRoot.render(React.createElement(Line, _config, null));
		return newRoot;
	}
	contextRoot.render(React.createElement(Line, _config, null));
	return contextRoot;
}
