import { CustomAreas, CustomLegends, CustomPoints } from "../layers";

const layers = [
	"grid",
	"markers",
	"axes",
	"areas",
	CustomAreas,
	"crosshair",
	"lines",
	"points",
	CustomPoints,
	"slices",
	"mesh",
	CustomLegends,
];

const layersMap = {
	AreasThreshold: CustomAreas,
	PointsDotsOnHover: CustomPoints,
	LegendsThreshold: CustomLegends,
};

export default function getLayers(config: any) {
	let _layers = layers;
	if (config._variant === "small") return ["lines"];
	if (config.layers && Array.isArray(config.layers)) {
		_layers = config.layers.map((layer) => {
			if (layersMap[layer]) return layersMap[layer];
			return layer;
		});
	}
	return _layers;
}
